#include "crarecreatedialog.hpp"
namespace mxh::ui{void cRareCreateDialog::SetRecipe(std::uint32_t r,std::vector<CreateMaterial>m){m_result=r;m_materials=std::move(m);m_filled.assign(m_materials.size(),false);}bool cRareCreateDialog::SetMaterial(std::size_t s,CreateMaterial m){if(s>=m_materials.size()||m.id==0||m.count<m_materials[s].count)return false;m_filled[s]=true;return true;}bool cRareCreateDialog::CanCreate()const noexcept{if(m_result==0||m_materials.empty()||m_filled.size()!=m_materials.size())return false;for(bool f:m_filled)if(!f)return false;return true;}bool cRareCreateDialog::Create(){if(!CanCreate())return false;return !m_callback||m_callback(m_result);}}
